#!/usr/bin/env python3

# Target P53 protein sequence
target_protein = ""

# DNA sequences from plasmids A, B, C, D
sequences = {
    'A': "",
    'B': "",
    'C': "",
    'D': ""
}

# Standard genetic code
codon_table = {
    'TTT': 'F', 'TTC': 'F', 'TTA': 'L', 'TTG': 'L',
    'TCT': 'S', 'TCC': 'S', 'TCA': 'S', 'TCG': 'S',
    'TAT': 'Y', 'TAC': 'Y', 'TAA': '*', 'TAG': '*',
    'TGT': 'C', 'TGC': 'C', 'TGA': '*', 'TGG': 'W',
    'CTT': 'L', 'CTC': 'L', 'CTA': 'L', 'CTG': 'L',
    'CCT': 'P', 'CCC': 'P', 'CCA': 'P', 'CCG': 'P',
    'CAT': 'H', 'CAC': 'H', 'CAA': 'Q', 'CAG': 'Q',
    'CGT': 'R', 'CGC': 'R', 'CGA': 'R', 'CGG': 'R',
    'ATT': 'I', 'ATC': 'I', 'ATA': 'I', 'ATG': 'M',
    'ACT': 'T', 'ACC': 'T', 'ACA': 'T', 'ACG': 'T',
    'AAT': 'N', 'AAC': 'N', 'AAA': 'K', 'AAG': 'K',
    'AGT': 'S', 'AGC': 'S', 'AGA': 'R', 'AGG': 'R',
    'GTT': 'V', 'GTC': 'V', 'GTA': 'V', 'GTG': 'V',
    'GCT': 'A', 'GCC': 'A', 'GCA': 'A', 'GCG': 'A',
    'GAT': 'D', 'GAC': 'D', 'GAA': 'E', 'GAG': 'E',
    'GGT': 'G', 'GGC': 'G', 'GGA': 'G', 'GGG': 'G'
}

def translate_dna(dna_sequence):
    """Translate DNA sequence to protein sequence"""
    protein = ""
    for i in range(0, len(dna_sequence), 3):
        codon = dna_sequence[i:i+3]
        if len(codon) == 3:
            amino_acid = codon_table.get(codon, 'X')
            if amino_acid == '*':
                break
            protein += amino_acid
    return protein

def compare_sequences(seq1, seq2):
    """Compare two sequences and return match percentage"""
    if len(seq1) != len(seq2):
        return 0.0
    matches = sum(1 for a, b in zip(seq1, seq2) if a == b)
    return (matches / len(seq1)) * 100

print("Target P53 protein sequence:")
print(target_protein)
print(f"Length: {len(target_protein)} amino acids\n")

print("Translating plasmid sequences:\n")

results = {}
for plasmid, dna_seq in sequences.items():
    translated = translate_dna(dna_seq)
    match_percentage = compare_sequences(target_protein, translated)
    results[plasmid] = {
        'translated': translated,
        'length': len(translated),
        'match': match_percentage
    }
    
    print(f"Plasmid {plasmid}:")
    print(f"Translated: {translated}")
    print(f"Length: {len(translated)} amino acids")
    print(f"Match with target: {match_percentage:.1f}%")
    
    if match_percentage == 100.0:
        print("*** PERFECT MATCH! ***")
    elif match_percentage > 95.0:
        print("*** Very close match ***")
    
    print()

# Find the best match
best_match = max(results.items(), key=lambda x: x[1]['match'])
print(f"Best match: Plasmid {best_match[0]} with {best_match[1]['match']:.1f}% similarity")

# Show differences for sequences that are close but not perfect
for plasmid, result in results.items():
    if 90 <= result['match'] < 100:
        print(f"\nDifferences in Plasmid {plasmid}:")
        target = target_protein
        translated = result['translated']
        min_len = min(len(target), len(translated))
        
        for i in range(min_len):
            if target[i] != translated[i]:
                print(f"Position {i+1}: Target='{target[i]}' vs Translated='{translated[i]}'")
        
        if len(target) != len(translated):
            print(f"Length difference: Target={len(target)}, Translated={len(translated)}")